import test from'node:test';import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{refreshDurationHints}from'./db-hint-refresh.mjs';import{balanceDatabaseFiles,validateDurationHints}from'./db-scheduling.mjs';
const file='test/known.test.ts',other='test/new.test.ts',blob='a'.repeat(40),different='b'.repeat(40),target='c'.repeat(40);
const fixture=()=>({prior:{schemaVersion:1,kind:'DURATION_HINTS_ONLY_NEVER_COVERAGE_OR_PASS',unknownDurationMs:15000,durationsMs:{[file]:3000}},target,sourceBlobs:{[file]:blob},observations:{[file]:[{runId:1,blob,durationMs:10000},{runId:2,blob,durationMs:24000}]},origins:[1,2].map(runId=>({runId,candidate:different,controller:different,conclusion:runId===1?'failure':'success'}))});
test('choose conservative maximum only from exact file blobs and convey no PASS',()=>{const x=fixture(),r=refreshDurationHints(x);assert.equal(r.profile.durationsMs[file],24000);assert.equal(r.assessment.adopted,1);assert.equal(r.assessment.releaseAuthorized,false);assert.equal(r.assessment.goalAchieved,false);assert.equal(x.prior.durationsMs[file],3000);});
test('changed file cannot use a faster prior observation and retains positive fallback',()=>{const x=fixture();x.sourceBlobs[file]=different;const r=refreshDurationHints(x);assert.equal(r.profile.durationsMs[file],15000);assert.deepEqual(r.assessment.fallback,[file]);});
test('unobserved source remains present with conservative fallback while foreign data cannot add files',()=>{const x=fixture();x.sourceBlobs[other]=different;x.observations['test/foreign.test.ts']=[{runId:1,blob,durationMs:100}];const r=refreshDurationHints(x);assert.equal(r.profile.durationsMs[other],15000);assert.equal(r.profile.durationsMs['test/foreign.test.ts'],undefined);});
test('already slower old hint is not lowered for a changed file',()=>{const x=fixture();x.sourceBlobs[file]=different;x.prior.durationsMs[file]=50000;assert.equal(refreshDurationHints(x).profile.durationsMs[file],50000);});
for(const[name,change]of Object.entries({zero:x=>x.observations[file][0].durationMs=0,negative:x=>x.observations[file][0].durationMs=-1,nonfinite:x=>x.observations[file][0].durationMs=Infinity,foreignOrigin:x=>x.observations[file][0].runId=99,duplicateOrigin:x=>x.origins[1].runId=1,duplicateInterval:x=>x.observations[file].push(x.observations[file][0]),badBlob:x=>x.observations[file][0].blob='HEAD',badPath:x=>x.sourceBlobs['test/../escape.test.ts']=blob}))test('refuse '+name,()=>{const x=fixture();change(x);assert.throws(()=>refreshDurationHints(x));});
test('published dataset covers all supplied target paths and retains unchanged scheduler capacity',()=>{const p=JSON.parse(readFileSync(new URL('./db-duration-hints.json',import.meta.url))),d=validateDurationHints(p),meta=p.blobBoundRefresh;assert.equal(meta.kind,'ADVISORY_TIMING_NOT_COVERAGE_OR_PASS');assert.equal(meta.releaseAuthorized,false);const files=[...Object.keys(meta.adoptedInputBlobs),...meta.changedOrUnobserved].sort();assert.equal(new Set(files).size,files.length);assert.equal(files.length,meta.files);assert(files.every(f=>Number.isSafeInteger(d[f])&&d[f]>0));const groups=balanceDatabaseFiles(files,24,d,p.unknownDurationMs);assert.equal(groups.length,Math.ceil(files.length/24));assert.deepEqual(groups.flat().sort(),files);assert(groups.every(g=>g.length<=24));});
